INSERT INTO item_weapon_profiles(item_id,weapon_role,weapon_category,handedness,damage_type,range_type,range_text,damage,weapon_effect_description,weapon_narrative_notes,source_system,source_external_id) SELECT item.id,seed.weapon_role,seed.weapon_category,seed.handedness,seed.damage_type,seed.range_type,seed.range_text,seed.damage,seed.weapon_effect_description,seed.weapon_narrative_notes,seed.source_system,seed.source_external_id FROM _curated_weapons seed JOIN _curated_items core ON core.ordinal=seed.item_ordinal JOIN items item ON item.source_system='serrian-tide-canonical-catalog' AND item.source_external_id=core.source_external_id;
