INSERT INTO item_armor_profiles(item_id,area_covered,soak,armor_category,armor_type,encumbrance_penalty,armor_effect_description,armor_narrative_notes,source_system,source_external_id) SELECT item.id,seed.area_covered,seed.soak,seed.armor_category,seed.armor_type,seed.encumbrance_penalty,seed.armor_effect_description,seed.armor_narrative_notes,seed.source_system,seed.source_external_id FROM _curated_armor seed JOIN _curated_items core ON core.ordinal=seed.item_ordinal JOIN items item ON item.source_system='serrian-tide-canonical-catalog' AND item.source_external_id=core.source_external_id;
